import{i as e,n as t,r as n,t as r}from"./es-vZKB7cQS.js";import{a as i,c as a,i as o,l as s,n as c,o as l,r as u,s as d,t as f,u as p}from"./es-JaumcI07.js";import{n as m,r as h,t as g}from"./es-mwrtuItc.js";import{t as _}from"./es-sZ9aav-o.js";import{i as v,n as y,r as b,t as x}from"./es-BJ6c1q7P.js";var S={Fi:()=>`Selección avanzada de modelos`,Fj:e,Fk:()=>`Úsalo si los metadatos faltan, son desconocidos o no se pueden leer. Los modelos no detectados siguen siendo seleccionables; al generar se comprueban y pueden resultar no compatibles.`,Fl:_,Fm:p,Fn:s,Fp:a,Fq:d,Fr:l,Fs:()=>`Cancel and discard`,Ft:()=>`Get audio so far`,Fv:n,Fw:()=>`Comprobando los metadatos de los modelos locales…`,Fx:t,Fz:()=>`The prompt needs more context. Shorten the text/reference or increase the context size.`,FA:()=>`Este es el tamaño de contexto solicitado. Se limita al contexto de entrenamiento del modelo y puede reducirse si falta memoria. Un contexto mayor usa más memoria y no acelera la generación. Es independiente del límite de pasos de audio.`,FB:i,FE:v,FF:()=>`Decodificando el audio generado…`,FG:()=>`Eliminar todos los audios`,FN:()=>`The model produced no audio samples. Check the model pair and try a short sentence with a different seed.`,FO:()=>`Finish generation and keep audio`,FP:()=>`Finish generation and keep audio ends further steps. Cancel and discard drops audio not yet captured. Audio already added to history remains.`,FR:()=>`Finishing the current step, then converting the audio…`,FS:()=>`Generate audio`,FT:b,FU:()=>`Audio generation failed. Report the code below and the [llama-cpp-browser] console diagnostics. GPU failures may require selecting CPU and trying again.`,FW:()=>`Generation stopped. No partial audio was published.`,FX:({count:e,mebibytes:t})=>`${e} resultado(s) · ${t} MiB de audio (más la memoria del reproductor)`,FY:()=>`Enter a short sentence for the first test.`,FZ:o,F_:()=>`Un espacio independiente para generar voz en el navegador. Con la aplicación, el entorno de ejecución y el modelo disponibles localmente, la generación funciona sin conexión. El texto y la voz de referencia no se envían a un servidor. Solo se necesita conexión para descargar archivos que falten o actualizaciones.`,Ga:r,Gd:u,Ge:()=>`El idioma inicial coincide con el de la aplicación cuando es compatible. Selecciona el idioma explícitamente. El valor predeterminado del modelo usa inglés en Qwen, no detección automática. Pocket usa el idioma con el que se entrenó, independientemente de este ajuste.`,Gg:()=>`Models and runtime`,Gh:c,Gk:y,Gl:()=>`Los candidatos se identifican mediante los metadatos del modelo local y su componente de audio seleccionado. Esto no garantiza compatibilidad ni calidad. La comprobación no carga modelos para inferencia ni los descarga.`,Gm:()=>`Import a matching backbone GGUF and audio mmproj together as one model folder, or download the pair with the repository browser below. Keep only one backbone (or its shards) and one matching mmproj in the folder. Chat model suggestions are not shown here.`,Gn:()=>`Supported native pipelines: Qwen3-TTS Base and Pocket TTS. CustomVoice and VoiceDesign are not supported by this screen. Compatibility is checked after loading, not guessed from filenames. Runtime profile settings are shared with browser chat inference.`,Go:()=>`Detailed native diagnostics in the console`,Gp:()=>`No se detectaron candidatos para generar audio.`,Gr:()=>`No detectado como modelo de audio`,Gt:()=>`Los audios terminados y sus ajustes permanecen en memoria mientras esta página esté abierta, incluso durante la siguiente generación. Puedes eliminarlos uno a uno o todos. No se guardan automáticamente: guarda los WAV necesarios antes de salir o recargar. La reproducción no se inicia sola.`,Gv:()=>`Preparing selected reference audio…`,Gw:()=>`Adds audio so far to history without ending generation. Qwen waits for a completed waveform block; short requests may finish before a preview is available. No automatic playback.`,Gx:()=>`Waiting for a safe audio boundary. Generation will continue.`,Gz:()=>`Esta opción solo controla el modelo auxiliar de audio; el principal sigue el perfil compartido. Seguir el perfil permite usar WebGPU cuando esté disponible, aunque algunas operaciones pueden usar la CPU. Forzar la CPU puede ser más lento, pero permite comparar.`,GN:()=>`Pocket requires a reference voice. Choose an audio file and try again.`,GS:()=>`Reinicializar el entorno`,GT:()=>`Tras un error, reinicializa sin recargar la página. Se conservan los modelos guardados, el texto y el historial de audio. No se interrumpen otras tareas activas.`,GU:()=>`Reinicializando el entorno…`,GX:x,GY:()=>`Open Models and runtime to select an available runtime and import a matching model pair.`,GZ:()=>`Token sampling controls apply to Qwen’s backbone. Top K, top P and seed also pass to the native audio helper. Pocket ignores token sampling and uses its native defaults. Temperature 0 does not guarantee deterministic audio. Step counts are not a predicted completion percentage or a fixed duration.`,G_:f,Hb:()=>`Mostrar todos los modelos guardados de llama.cpp browser`,Hc:()=>`Elegir entre todos los modelos`,Hd:()=>`El límite de pasos es un tope de seguridad, no una duración objetivo. La generación termina antes si el modelo finaliza. Aumentarlo permite audios más largos, pero puede alargar la espera si el modelo no se detiene.`,He:({completed:e,maximum:t})=>`${e} / ${t} steps (limit)`,Hh:()=>`Stopping and releasing the model…`,Hj:()=>`This model pair does not expose a supported audio-generation pipeline. Choose matching Qwen3-TTS Base or Pocket files, not a chat model or vision projector.`,Hk:()=>`Waiting for the inference lane…`,Ql:h,Qm:m,Qt:g};export{S as default};
